```java
import java.util.Random;
import java.util.Scanner;

public class GuessMyNumber {
    public static void main(String[] args) {
        Scanner keyboard = new Scanner(System.in);
        Random random = new Random();

        System.out.println("Welcome to the Guess My Number Game!");
        System.out.println();
        System.out.println("First, let's set the range.");

        int min = readInteger(
                keyboard,
                "Enter the minimum number (e.g., 1): "
        );

        int max;

        while (true) {
            max = readInteger(
                    keyboard,
                    "Enter the maximum number (e.g., 100): "
            );

            if (max > min) {
                break;
            }

            System.out.println(
                    "The maximum must be greater than the minimum."
            );
        }

        // The + 1 allows max to be included.
        int secretNumber = random.nextInt(max - min + 1) + min;

        System.out.println();
        System.out.println(
                "I'm thinking of a number between " + min + " and "
                + max + " (including both). Can you guess what it is?"
        );

        int guessesLeft = 5;
        int attempts = 0;
        boolean won = false;

        System.out.println("You have " + guessesLeft + " guesses.");

        while (guessesLeft > 0) {
            System.out.println();

            int guess = readInteger(keyboard, "Type a number: ");

            // An out-of-range number does not use a guess.
            if (guess < min || guess > max) {
                System.out.println(
                        "Your guess (" + guess + ") is out of the range ["
                        + min + ", " + max + "]. Please guess again "
                        + "within the range."
                );
                continue;
            }

            attempts++;
            System.out.println("Your guess is: " + guess);

            if (guess == secretNumber) {
                System.out.println(
                        "The number I was thinking of is: " + secretNumber
                );
                System.out.println(
                        "Congratulations! You guessed it in "
                        + attempts + " attempts!"
                );

                won = true;
                break;
            }

            guessesLeft--;

            if (guess < secretNumber) {
                System.out.println(
                        "Too low! You have " + guessesLeft + " guesses left."
                );
            } else {
                System.out.println(
                        "Too high! You have " + guessesLeft + " guesses left."
                );
            }
        }

        if (!won) {
            System.out.println("Sorry, you ran out of guesses.");
            System.out.println(
                    "The number I was thinking of was: " + secretNumber
            );
        }

        keyboard.close();
    }

    private static int readInteger(Scanner keyboard, String prompt) {
        while (true) {
            System.out.print(prompt);
            String text = keyboard.nextLine();

            try {
                return Integer.parseInt(text.trim());
            } catch (NumberFormatException e) {
                System.out.println("Please enter a valid whole number.");
            }
        }
    }
}
```

There are two different kinds of validation here:

- **Number validation:** The user entered a whole number rather than text or a decimal.
- **Range validation:** The number is an integer, but it is outside the selected game range.

In the sample behavior, an out-of-range input such as `12` does not count as an attempt, which is why the `continue` occurs before `attempts++`.

